-- KHUNYUI DATABASE 003 — CUSTOMER + OWNER RPC FUNCTIONS\n\n-- ---------- guards ----------\ncreate or replace function public.assert_store_member(p_store_id uuid) returns void\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\nbegin\n  if not public.is_store_member(p_store_id) then raise exception 'NOT_AUTHORIZED' using errcode='42501'; end if;\nend $$;\n\n-- ---------- customer public ----------\ncreate or replace function public.customer_public_state(p_qr_token text default null)\nreturns jsonb language plpgsql security definer set search_path=public,pg_temp as $$\ndeclare q public.qr_points%rowtype; s public.stores%rowtype; a public.customer_access%rowtype;\nbegin\n  if p_qr_token is not null and btrim(p_qr_token)<>'' then\n    select * into q from public.qr_points where token=p_qr_token and active=true limit 1;\n  else\n    select * into q from public.qr_points where active=true order by created_at limit 1;\n  end if;\n  if q.id is null then raise exception 'QR_NOT_FOUND'; end if;\n  select * into s from public.stores where id=q.store_id;\n  select * into a from public.customer_access where store_id=q.store_id;\n  return jsonb_build_object(\n    'store',jsonb_build_object('id',s.id,'store_name',s.store_name,'branch',s.branch,'accepting_orders',s.accepting_orders),\n    'access',jsonb_build_object('home',coalesce(a.home,true),'somtam',coalesce(a.somtam,true),'yum',coalesce(a.yum,true),'cart',coalesce(a.cart,true)),\n    'context',jsonb_build_object('qr_token',q.token,'label',q.label,'fulfillment_type',q.fulfillment_type,'table_label',q.table_label),\n    'menu',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'code',m.code,'cat',m.cat,'subcategory',m.subcategory,'category',m.category,'name',m.name,'price',m.price,'description',m.description,'image_url',m.image_url,'is_available',m.is_available,'sort_order',m.sort_order) order by m.sort_order) from public.menu_items m where m.store_id=q.store_id),'[]'::jsonb)\n  );\nend $$;\n\ncreate or replace function public.customer_place_order(p_qr_token text,p_payload jsonb)\nreturns jsonb language plpgsql security definer set search_path=public,pg_temp as $$\ndeclare\n  q public.qr_points%rowtype; s public.stores%rowtype; m public.menu_items%rowtype;\n  o_id uuid:=gen_random_uuid(); tracking text:=encode(gen_random_bytes(18),'hex');\n  d date; seq int; ono text; elem jsonb; qty int; total numeric(12,2):=0; cnt int:=0; pm text; n text;\nbegin\n  select * into q from public.qr_points where token=p_qr_token and active=true limit 1;\n  if q.id is null then raise exception 'QR_NOT_FOUND'; end if;\n  select * into s from public.stores where id=q.store_id;\n  if s.id is null or s.accepting_orders=false then raise exception 'STORE_NOT_ACCEPTING'; end if;\n  if jsonb_typeof(coalesce(p_payload->'items','[]'::jsonb))<>'array' or jsonb_array_length(coalesce(p_payload->'items','[]'::jsonb))=0 then raise exception 'EMPTY_ORDER'; end if;\n  d=(now() at time zone s.timezone)::date;\n  insert into public.order_counters(store_id,order_date,last_value) values(s.id,d,1)\n  on conflict(store_id,order_date) do update set last_value=public.order_counters.last_value+1\n  returning last_value into seq;\n  ono='A'||lpad(seq::text,3,'0');\n  pm=lower(coalesce(p_payload->>'payment_method','cash')); if pm not in ('cash','qr') then pm='cash'; end if;\n  n=nullif(left(btrim(coalesce(p_payload->>'note','')),500),'');\n  insert into public.orders(id,store_id,qr_point_id,order_no,tracking_token,status,payment_method,payment_status,fulfillment_type,table_label,note,total,item_count)\n  values(o_id,s.id,q.id,ono,tracking,'new',pm,case when pm='qr' then 'pending' else 'unpaid' end,q.fulfillment_type,q.table_label,n,0,0);\n  for elem in select value from jsonb_array_elements(p_payload->'items') loop\n    qty=greatest(1,least(99,coalesce(nullif(elem->>'quantity','')::int,1)));\n    select * into m from public.menu_items where store_id=s.id and code=elem->>'code' and is_available=true limit 1;\n    if m.id is null then raise exception 'MENU_UNAVAILABLE:%',coalesce(elem->>'code','?'); end if;\n    insert into public.order_items(order_id,store_id,menu_item_id,menu_code,name,unit_price,quantity,line_total,note,modifiers)\n    values(o_id,s.id,m.id,m.code,m.name,m.price,qty,m.price*qty,nullif(left(btrim(coalesce(elem->>'note','')),300),''),coalesce(elem->'modifiers','[]'::jsonb));\n    total=total+(m.price*qty); cnt=cnt+qty;\n  end loop;\n  update public.orders set total=total,item_count=cnt where id=o_id;\n  insert into public.order_events(order_id,store_id,event_type,to_status,payload) values(o_id,s.id,'created','new',jsonb_build_object('qr_point_id',q.id));\n  return jsonb_build_object('order_id',o_id,'order_no',ono,'tracking_token',tracking,'status','new','total',total,'item_count',cnt);\nexception when others then\n  -- entire function call is atomic; any failure rolls back the order and its items\n  raise;\nend $$;\n\ncreate or replace function public.customer_order_status(p_tracking_token text)\nreturns jsonb language plpgsql security definer set search_path=public,pg_temp as $$\ndeclare o public.orders%rowtype;\nbegin\n  select * into o from public.orders where tracking_token=p_tracking_token limit 1;\n  if o.id is null then raise exception 'ORDER_NOT_FOUND'; end if;\n  return jsonb_build_object('order_id',o.id,'order_no',o.order_no,'status',o.status,'payment_status',o.payment_status,'total',o.total,'item_count',o.item_count,'updated_at',o.updated_at,\n    'items',coalesce((select jsonb_agg(jsonb_build_object('code',i.menu_code,'name',i.name,'quantity',i.quantity,'unit_price',i.unit_price,'line_total',i.line_total,'note',i.note,'modifiers',i.modifiers) order by i.created_at) from public.order_items i where i.order_id=o.id),'[]'::jsonb));\nend $$;\n\n-- ---------- owner access ----------\ncreate or replace function public.owner_access_check() returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare sm public.store_members%rowtype;\nbegin\n  select * into sm from public.store_members where user_id=(select auth.uid()) order by case role when 'owner' then 1 when 'manager' then 2 else 3 end limit 1;\n  if sm.store_id is null then return jsonb_build_object('allowed',false); end if;\n  return jsonb_build_object('allowed',true,'store_id',sm.store_id,'role',sm.role);\nend $$;\n\ncreate or replace function public.owner_dashboard_summary(p_store_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare s public.stores%rowtype; day_start timestamptz; day_end timestamptz;\nbegin\n  perform public.assert_store_member(p_store_id); select * into s from public.stores where id=p_store_id;\n  day_start=((now() at time zone s.timezone)::date::timestamp at time zone s.timezone); day_end=day_start+interval '1 day';\n  return jsonb_build_object(\n    'store',jsonb_build_object('name',s.store_name,'branch',s.branch,'accepting_orders',s.accepting_orders),\n    'order_counts',jsonb_build_object('new',(select count(*) from public.orders where store_id=p_store_id and status='new'),'preparing',(select count(*) from public.orders where store_id=p_store_id and status='preparing'),'ready',(select count(*) from public.orders where store_id=p_store_id and status='ready')),\n    'today',jsonb_build_object('orders_total',(select count(*) from public.orders where store_id=p_store_id and created_at>=day_start and created_at<day_end and status<>'cancelled'),'sales_total',coalesce((select sum(total) from public.orders where store_id=p_store_id and created_at>=day_start and created_at<day_end and status<>'cancelled'),0),'paid_total',coalesce((select sum(total) from public.orders where store_id=p_store_id and created_at>=day_start and created_at<day_end and payment_status='paid'),0)),\n    'payments',jsonb_build_object('qr',coalesce((select sum(total) from public.orders where store_id=p_store_id and created_at>=day_start and created_at<day_end and payment_method='qr' and status<>'cancelled'),0),'cash',coalesce((select sum(total) from public.orders where store_id=p_store_id and created_at>=day_start and created_at<day_end and payment_method='cash' and status<>'cancelled'),0)),\n    'fulfillment',jsonb_build_object('dine_in',(select count(*) from public.orders where store_id=p_store_id and created_at>=day_start and created_at<day_end and fulfillment_type='dine_in' and status<>'cancelled'),'takeaway',(select count(*) from public.orders where store_id=p_store_id and created_at>=day_start and created_at<day_end and fulfillment_type='takeaway' and status<>'cancelled')),\n    'menu',jsonb_build_object('active',(select count(*) from public.menu_items where store_id=p_store_id and is_available=true),'inactive',(select count(*) from public.menu_items where store_id=p_store_id and is_available=false)),\n    'recent_orders',coalesce((select jsonb_agg(x.obj order by x.created_at desc) from (select o.created_at,jsonb_build_object('id',o.id,'order_no',o.order_no,'created_at',o.created_at,'status',o.status,'total',o.total) obj from public.orders o where o.store_id=p_store_id order by o.created_at desc limit 5)x),'[]'::jsonb)\n  );\nend $$;\n\ncreate or replace function public.owner_today_orders(p_store_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare s public.stores%rowtype; ds timestamptz; de timestamptz;\nbegin\n perform public.assert_store_member(p_store_id); select * into s from public.stores where id=p_store_id; ds=((now() at time zone s.timezone)::date::timestamp at time zone s.timezone);de=ds+interval '1 day';\n return coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'order_no',o.order_no,'created_at',o.created_at,'status',o.status,'item_count',o.item_count,'total',o.total,'payment_method',o.payment_method,'payment_status',o.payment_status,'fulfillment_type',o.fulfillment_type,'branch',s.branch,'items',coalesce((select jsonb_agg(jsonb_build_object('name',i.name,'quantity',i.quantity) order by i.created_at) from public.order_items i where i.order_id=o.id),'[]'::jsonb)) order by o.created_at desc) from public.orders o where o.store_id=p_store_id and o.created_at>=ds and o.created_at<de),'[]'::jsonb);\nend $$;\n\ncreate or replace function public.owner_order_detail(p_store_id uuid,p_order_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare o public.orders%rowtype; s public.stores%rowtype;\nbegin\n perform public.assert_store_member(p_store_id); select * into o from public.orders where id=p_order_id and store_id=p_store_id; if o.id is null then raise exception 'ORDER_NOT_FOUND'; end if; select * into s from public.stores where id=p_store_id;\n return jsonb_build_object('id',o.id,'order_no',o.order_no,'created_at',o.created_at,'status',o.status,'fulfillment_type',o.fulfillment_type,'table_label',o.table_label,'note',o.note,'total',o.total,'item_count',o.item_count,'payment_method',o.payment_method,'payment_status',o.payment_status,'completed_at',o.completed_at,'branch',s.branch,'items',coalesce((select jsonb_agg(jsonb_build_object('code',i.menu_code,'name',i.name,'quantity',i.quantity,'unit_price',i.unit_price,'line_total',i.line_total,'note',i.note,'modifiers',i.modifiers) order by i.created_at) from public.order_items i where i.order_id=o.id),'[]'::jsonb));\nend $$;\n\ncreate or replace function public.owner_advance_order_status(p_store_id uuid,p_order_id uuid,p_expected_status text,p_next_status text) returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare o public.orders%rowtype;\nbegin\n perform public.assert_store_member(p_store_id);\n if (p_expected_status,p_next_status) not in (('new','preparing'),('preparing','ready'),('ready','completed')) then raise exception 'INVALID_STATUS_TRANSITION'; end if;\n select * into o from public.orders where id=p_order_id and store_id=p_store_id for update; if o.id is null then raise exception 'ORDER_NOT_FOUND'; end if; if o.status<>p_expected_status then raise exception 'STATUS_CHANGED'; end if;\n update public.orders set status=p_next_status,completed_at=case when p_next_status='completed' then now() else completed_at end where id=o.id returning * into o;\n insert into public.order_events(order_id,store_id,event_type,from_status,to_status,actor_user_id) values(o.id,p_store_id,'status_changed',p_expected_status,p_next_status,(select auth.uid()));\n return jsonb_build_object('id',o.id,'order_no',o.order_no,'status',o.status,'completed_at',o.completed_at);\nend $$;\n\ncreate or replace function public.owner_mark_cash_paid(p_store_id uuid,p_order_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare o public.orders%rowtype;\nbegin\n perform public.assert_store_member(p_store_id); select * into o from public.orders where id=p_order_id and store_id=p_store_id for update; if o.id is null then raise exception 'ORDER_NOT_FOUND'; end if; if o.payment_method<>'cash' then raise exception 'NOT_CASH_ORDER'; end if;\n update public.orders set payment_status='paid',payment_at=coalesce(payment_at,now()) where id=o.id returning * into o;\n insert into public.order_events(order_id,store_id,event_type,payload,actor_user_id) values(o.id,p_store_id,'payment_paid',jsonb_build_object('method','cash','amount',o.total),(select auth.uid()));\n return jsonb_build_object('id',o.id,'payment_status',o.payment_status,'payment_at',o.payment_at,'total',o.total);\nend $$;\n\ncreate or replace function public.owner_menu_list(p_store_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\nbegin perform public.assert_store_member(p_store_id); return coalesce((select jsonb_agg(to_jsonb(m) order by m.sort_order) from public.menu_items m where store_id=p_store_id),'[]'::jsonb); end $$;\n\ncreate or replace function public.owner_menu_detail(p_store_id uuid,p_menu_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare m public.menu_items%rowtype;begin perform public.assert_store_member(p_store_id);select * into m from public.menu_items where store_id=p_store_id and id=p_menu_id;if m.id is null then raise exception 'MENU_NOT_FOUND';end if;return to_jsonb(m);end $$;\n\ncreate or replace function public.owner_store_settings(p_store_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare s public.stores%rowtype;a public.customer_access%rowtype;begin perform public.assert_store_member(p_store_id);select * into s from public.stores where id=p_store_id;select * into a from public.customer_access where store_id=p_store_id;return jsonb_build_object('store_name',s.store_name,'name',s.store_name,'branch',s.branch,'accepting_orders',s.accepting_orders,'customer_access',jsonb_build_object('home',coalesce(a.home,true),'somtam',coalesce(a.somtam,true),'yum',coalesce(a.yum,true),'cart',coalesce(a.cart,true)));end $$;\n\ncreate or replace function public.owner_set_accepting_orders(p_store_id uuid,p_accepting_orders boolean) returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare s public.stores%rowtype;begin perform public.assert_store_member(p_store_id);update public.stores set accepting_orders=p_accepting_orders where id=p_store_id returning * into s;return jsonb_build_object('accepting_orders',s.accepting_orders);end $$;\n\ncreate or replace function public.owner_update_store_profile(p_store_id uuid,p_store_name text,p_branch text) returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare s public.stores%rowtype;begin perform public.assert_store_member(p_store_id);if btrim(p_store_name)='' or btrim(p_branch)='' then raise exception 'INVALID_STORE_PROFILE';end if;update public.stores set store_name=left(btrim(p_store_name),120),branch=left(btrim(p_branch),120) where id=p_store_id returning * into s;return jsonb_build_object('store_name',s.store_name,'name',s.store_name,'branch',s.branch);end $$;\n\ncreate or replace function public.owner_notification_preferences(p_store_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare p public.owner_preferences%rowtype;begin perform public.assert_store_member(p_store_id);insert into public.owner_preferences(store_id,user_id) values(p_store_id,(select auth.uid())) on conflict(store_id,user_id) do nothing;select * into p from public.owner_preferences where store_id=p_store_id and user_id=(select auth.uid());return jsonb_build_object('notify_new_orders',p.notify_new_orders,'sound_new_orders',p.sound_new_orders);end $$;\n\ncreate or replace function public.owner_update_notification_preferences(p_store_id uuid,p_notify_new_orders boolean,p_sound_new_orders boolean) returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare p public.owner_preferences%rowtype;begin perform public.assert_store_member(p_store_id);insert into public.owner_preferences(store_id,user_id,notify_new_orders,sound_new_orders) values(p_store_id,(select auth.uid()),p_notify_new_orders,p_sound_new_orders) on conflict(store_id,user_id) do update set notify_new_orders=excluded.notify_new_orders,sound_new_orders=excluded.sound_new_orders returning * into p;return jsonb_build_object('notify_new_orders',p.notify_new_orders,'sound_new_orders',p.sound_new_orders);end $$;\n\ncreate or replace function public.owner_update_customer_access(p_store_id uuid,p_key text,p_enabled boolean) returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare a public.customer_access%rowtype;begin perform public.assert_store_member(p_store_id);if p_key not in ('home','somtam','yum','cart') then raise exception 'INVALID_ACCESS_KEY';end if;insert into public.customer_access(store_id) values(p_store_id) on conflict(store_id) do nothing;execute format('update public.customer_access set %I=$1 where store_id=$2',p_key) using p_enabled,p_store_id;select * into a from public.customer_access where store_id=p_store_id;return jsonb_build_object('customer_access',jsonb_build_object('home',a.home,'somtam',a.somtam,'yum',a.yum,'cart',a.cart));end $$;\n\ncreate or replace function public.owner_finance_summary(p_store_id uuid,p_start_date date,p_end_date date,p_timezone text default 'Asia/Bangkok') returns jsonb\nlanguage plpgsql security definer set search_path=public,pg_temp as $$\ndeclare s public.stores%rowtype;ds timestamptz;de timestamptz;begin perform public.assert_store_member(p_store_id);select * into s from public.stores where id=p_store_id;ds=(p_start_date::timestamp at time zone coalesce(nullif(p_timezone,''),s.timezone));de=((p_end_date+1)::timestamp at time zone coalesce(nullif(p_timezone,''),s.timezone));return jsonb_build_object('store',jsonb_build_object('branch',s.branch),'new_orders_count',(select count(*) from public.orders where store_id=p_store_id and status='new'),'summary',jsonb_build_object('sales_total',coalesce((select sum(total) from public.orders where store_id=p_store_id and created_at>=ds and created_at<de and status<>'cancelled'),0),'collected_total',coalesce((select sum(total) from public.orders where store_id=p_store_id and created_at>=ds and created_at<de and payment_status='paid'),0),'orders_total',(select count(*) from public.orders where store_id=p_store_id and created_at>=ds and created_at<de and status<>'cancelled')),'payments',jsonb_build_object('qr',coalesce((select sum(total) from public.orders where store_id=p_store_id and created_at>=ds and created_at<de and payment_method='qr' and status<>'cancelled'),0),'cash',coalesce((select sum(total) from public.orders where store_id=p_store_id and created_at>=ds and created_at<de and payment_method='cash' and status<>'cancelled'),0)),'pending_cash',jsonb_build_object('count',(select count(*) from public.orders where store_id=p_store_id and created_at>=ds and created_at<de and payment_method='cash' and payment_status<>'paid' and status<>'cancelled'),'total',coalesce((select sum(total) from public.orders where store_id=p_store_id and created_at>=ds and created_at<de and payment_method='cash' and payment_status<>'paid' and status<>'cancelled'),0)),'orders',jsonb_build_object('total',(select count(*) from public.orders where store_id=p_store_id and created_at>=ds and created_at<de and status<>'cancelled'),'completed',(select count(*) from public.orders where store_id=p_store_id and created_at>=ds and created_at<de and status='completed'),'in_progress',(select count(*) from public.orders where store_id=p_store_id and created_at>=ds and created_at<de and status in('new','preparing','ready'))),'transactions',coalesce((select jsonb_agg(jsonb_build_object('order_id',o.id,'id',o.id,'order_no',o.order_no,'payment_at',o.payment_at,'updated_at',o.updated_at,'created_at',o.created_at,'payment_method',o.payment_method,'payment_status',o.payment_status,'amount',o.total,'total',o.total) order by o.created_at desc) from public.orders o where o.store_id=p_store_id and o.created_at>=ds and o.created_at<de),'[]'::jsonb));end $$;\n\n-- Explicit execution grants. Customer functions are safe SECURITY DEFINER boundaries; direct anon table access remains revoked.\nrevoke execute on function public.customer_place_order(text,jsonb) from public;\nrevoke execute on function public.customer_order_status(text) from public;\nrevoke execute on function public.customer_public_state(text) from public;\ngrant execute on function public.customer_place_order(text,jsonb),public.customer_order_status(text),public.customer_public_state(text) to anon,authenticated;\n\ngrant execute on function public.owner_access_check(),public.owner_dashboard_summary(uuid),public.owner_today_orders(uuid),public.owner_order_detail(uuid,uuid),public.owner_advance_order_status(uuid,uuid,text,text),public.owner_mark_cash_paid(uuid,uuid),public.owner_menu_list(uuid),public.owner_menu_detail(uuid,uuid),public.owner_store_settings(uuid),public.owner_set_accepting_orders(uuid,boolean),public.owner_update_store_profile(uuid,text,text),public.owner_notification_preferences(uuid),public.owner_update_notification_preferences(uuid,boolean,boolean),public.owner_update_customer_access(uuid,text,boolean),public.owner_finance_summary(uuid,date,date,text) to authenticated;\n